from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png')).astype(float)
# print detailed HSV-ish values for face region rows 87-101 every pixel, chars based on hue/dark
for y in range(84,103):
 s=''
 for x in range(90,120):
  r,g,b=im[y,x]
  if r>g+5 and g>b+25:
   c='Y'
  elif max(r,g,b)<50:
   c='#'
  elif max(r,g,b)<85:
   c='D'
  elif max(r,g,b)<115:
   c='d'
  elif max(r,g,b)<145:
   c='m'
  else:
   c='.'
  s+=c
 print(f'{y:3} {s}')
